// Obtener los datos directamente (n8n ya los pasa en items[0].json)
const inputData = items[0].json;

// Como tu JSON tiene los datos directamente, no necesitas [0]
const data = Array.isArray(inputData) ? inputData[0] : inputData;

// ------------------
// UTILIDADES (SOLO PARA TIEMPOS)
// ------------------

function horasADecimal(horaStr) {
    if (!horaStr || horaStr === "00:00") return 0;
    const [h, m] = horaStr.split(":").map(Number);
    return h + (m / 60);
}

function formatoHoras(horasDecimal) {
    const horas = Math.floor(horasDecimal);
    const minutos = Math.round((horasDecimal - horas) * 60);
    return `${horas.toString().padStart(2, '0')}:${minutos.toString().padStart(2, '0')}`;
}

function minutosAHoras(minutos) {
    const horas = Math.floor(minutos / 60);
    const mins = minutos % 60;
    return `${horas.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
}

// ------------------
// 1. TABLA PARÁMETROS (COMPLETOS - SE MANTIENEN)
// ------------------

const parametrosLista = [];

if (data.Tabla_Parametros && data.Tabla_Parametros.Datos) {
    for (const row of data.Tabla_Parametros.Datos) {
        const nombreCompleto = `${row.nombre_concepto_id} - ${row.nombre_tiempo_id}`;
        parametrosLista.push({
            concepto: nombreCompleto,
            valor: row.valor_monetario,
            valorFormateado: new Intl.NumberFormat('es-CO', {
                style: 'currency',
                currency: 'COP',
                minimumFractionDigits: 2,
                maximumFractionDigits: 2
            }).format(row.valor_monetario)
        });
    }
}

// ------------------
// 2. TABLA DETALLE (SOLO DATOS EN BRUTO)
// ------------------

const detalleRows = [];
let totalHorasDecimal = 0;

if (data.Tabla_Datos && data.Tabla_Datos.Rows) {
    for (const row of data.Tabla_Datos.Rows) {

        const horasTotalesDecimal = horasADecimal(row.Horas);

        // Acumular solo horas totales
        totalHorasDecimal += horasTotalesDecimal;

        detalleRows.push({
            responsable: row.responsable_id || "N/A",
            dia: row.Dia,
            fecha: row.fecha_turno,
            hora_inicio: row.hora_inicio,
            hora_fin: row.hora_fin,
            horas_totales: row.Horas,
            propina: row.Propinas || 0,
            sede: row.sede || "N/A"
            // ❌ ELIMINADO: horas_diurnas
            // ❌ ELIMINADO: horas_nocturnas
            // ❌ ELIMINADO: TODOS los cálculos monetarios
        });
    }
}

// ------------------
// 2.5 TABLA PROPINAS (SOLO TIEMPOS, SIN MONTO) - CORREGIDO: Tabla_Apoyos
// ------------------

const propinasRows = [];
let totalMinutosPropinas = 0;
let totalHorasPropinasDecimal = 0;

if (data.Tabla_Apoyos && data.Tabla_Apoyos.Datos) {
    for (const row of data.Tabla_Apoyos.Datos) {
        const minutos = row.tiempo_minutos || 0;

        totalMinutosPropinas += minutos;

        propinasRows.push({
            fecha_turno: row.fecha_turno,
            responsable_turno_id: row.responsable_turno_id,
            apoyo_responsable_id: row.apoyo_responsable_id,
            tiempo_minutos: minutos,
            tiempo_horas: row.tiempo_horas || minutosAHoras(minutos),
            tiempo_texto: row.tiempo_texto || `${Math.floor(minutos / 60)} horas ${minutos % 60} minutos`,
            hora_inicio: row.hora_inicio,
            hora_fin: row.hora_fin,
            propina: row.propina || 0,
            sede: row.sede// ✅ ÚNICO CAMBIO: se añadió este campo
            // ❌ ELIMINADO: propina (valor monetario)
            // ❌ ELIMINADO: propina_formato
        });
    }

    totalHorasPropinasDecimal = totalMinutosPropinas / 60;
}

// ------------------
// 3. TABLA RESUMEN (SOLO TIEMPOS TOTALES)
// ------------------

const resumenTiempos = {
    total_horas_trabajadas: totalHorasDecimal,
    total_horas_trabajadas_formato: formatoHoras(totalHorasDecimal),
    total_horas_propinas: totalHorasPropinasDecimal,
    total_horas_propinas_formato: formatoHoras(totalHorasPropinasDecimal)
};

// ------------------
// 4. TABLA TOTALES GENERALES (SOLO TIEMPOS Y CONTADORES)
// ------------------

const diasTrabajados = data.Tabla_Datos ? data.Tabla_Datos.Rows.length : 0;

const totalesGenerales = {
    dias_trabajados: diasTrabajados,
    horas_trabajadas: totalHorasDecimal,
    horas_trabajadas_formato: formatoHoras(totalHorasDecimal),
    horas_propinas: totalHorasPropinasDecimal,
    horas_propinas_formato: formatoHoras(totalHorasPropinasDecimal),
    total_apoyos: propinasRows.length
    // ❌ ELIMINADO: TODOS los cálculos monetarios
    // ❌ ELIMINADO: clasificaciones de tiempo (diurnas/nocturnas/dominicales)
};

// ------------------
// RETORNO PARA N8N
// ------------------

return [{
    json: {
        // Tabla 1: Parámetros configurados (COMPLETOS)
        parametros: parametrosLista,

        // Tabla 2: Detalle con datos en bruto
        detalle: detalleRows,

        // Tabla 3: Propinas y apoyos (sin montos)
        apoyos: propinasRows,

        // Tabla 4: Resumen de tiempos
        resumen_tiempos: resumenTiempos,

        // Tabla 5: Totales generales (solo tiempos)
        totales: totalesGenerales,

        // Datos adicionales útiles
        metadata: {
            total_filas_procesadas: detalleRows.length,
            total_apoyos_procesados: propinasRows.length,
            fecha_proceso: new Date().toISOString()
        }
    }
}];

